"use client";

import { useEffect, useState } from "react";
import axios from "axios";
import { useAuth } from "../../store/auth";
import { useRouter } from "next/navigation";

export default function CartPage() {
  const [cartItems, setCartItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const { token, user } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!token) {
      router.push("/login");
      return;
    }

    axios
      .get("http://127.0.0.1:8000/api/cart/", {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        setCartItems(res.data);
        setLoading(false);
      })
      .catch(() => {
        alert("Failed to load cart");
        setLoading(false);
      });
  }, [token, router]);

  const placeOrder = async () => {
    try {
      await axios.post(
        "http://127.0.0.1:8000/api/orders/",
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert("Order placed successfully! No payment needed");
      setCartItems([]);
    } catch {
      alert("Order failed");
    }
  };

  if (!token) return null;

  if (loading)
    return <div className="text-center py-20 text-xl">Loading cart...</div>;

  const total = cartItems.reduce(
    (sum: number, item: any) => sum + item.quantity * item.product_price,
    0
  );

  return (
    <div className="max-w-4xl mx-auto px-6 py-16">
      <h1 className="text-4xl font-bold text-[var(--wave-blue)] mb-10 text-center">
        Your Cart
      </h1>

      {cartItems.length === 0 ? (
        <div className="text-center py-20 text-2xl text-gray-500">
          Your cart is empty.{" "}
          <a href="/products" className="text-[var(--wave-blue)] underline">
            Shop now
          </a>
        </div>
      ) : (
        <div className="space-y-6">
          {cartItems.map((item: any) => (
            <div
              key={item.id}
              className="bg-white p-8 rounded-xl shadow-lg flex justify-between items-center"
            >
              <div>
                <h3 className="text-2xl font-bold">{item.product_name}</h3>
                <p className="text-gray-600">
                  Quantity: {item.quantity} × ${item.product_price}
                </p>
              </div>
              <span className="text-2xl font-bold text-[var(--wave-blue)]">
                ${(item.quantity * item.product_price).toFixed(2)}
              </span>
            </div>
          ))}

          <div className="text-right mt-10">
            <p className="text-3xl font-bold mb-6">
              Total:{" "}
              <span className="text-[var(--wave-blue)]">
                ${total.toFixed(2)}
              </span>
            </p>
            <button
              onClick={placeOrder}
              className="bg-[var(--wave-blue)] text-white px-12 py-5 rounded-full text-xl hover:bg-blue-700 transition text-shadow"
            >
              Place Order (Free Checkout)
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
